using System;
using System.Linq;
using System.Reflection;
using System.IO;
using LastRail.Diagnostics;
using LastRail.Presentation.MissionShell;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
public class OrdinaryDamageOwnerTests {
 [TestCase(false)][TestCase(true)] public void TerminalWriteInterruptionRestoresOneCommittedOutcome(bool committedBeforeFailure){
  var f=Factory();string saved=null;long revision=0;bool interrupt=false;
  Func<RestoredCombatCheckpoint> load=()=>saved==null?null:(RestoredCombatCheckpoint)Activator.CreateInstance(typeof(RestoredCombatCheckpoint),BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{BasicCombatSimulation.RestoreLocalState(saved,f.Create),revision},null);
  Func<BasicCombatSimulation,long,long> save=(state,expected)=>{Assert.AreEqual(revision,expected);if(interrupt&&!committedBeforeFailure)throw new IOException("before commit");saved=state.CaptureLocalState();revision++;if(interrupt)throw new IOException("after commit before acknowledgement");return revision;};
  var driver=new CombatSceneDriver(f.Create,load,save,()=>true);driver.Open();
  var fatal=Damage(f.Original.Train.TrainId,"TRAIN");fatal["command"]["numeric"]["base"]=new JObject{["numerator"]="100000",["denominator"]="1"};
  driver.ScheduleResolvedOrdinaryEffect(fatal);driver.ScheduleResolvedOrdinaryEffect(Damage("op_kyle","OPERATOR",2));
  interrupt=true;Assert.Throws<IOException>(()=>driver.Advance(500000,1));Assert.AreEqual(BasicCombatOutcome.Running,driver.Outcome);Assert.IsTrue(driver.RecoveryRequired);Assert.Throws<InvalidOperationException>(()=>driver.CaptureCommittedState());
  interrupt=false;var reopened=new CombatSceneDriver(f.Create,load,save,()=>true);reopened.Open();
  Assert.AreEqual(committedBeforeFailure?BasicCombatOutcome.Failure:BasicCombatOutcome.Running,reopened.Outcome);
  if(!committedBeforeFailure)reopened.Advance(500000,1);
  Assert.AreEqual(BasicCombatOutcome.Failure,reopened.Outcome);var terminal=reopened.CaptureCommittedState();
  var state=BasicCombatSimulation.RestoreLocalState(terminal.StateJson,f.Create);Assert.AreEqual(0,state.GetHp(f.Original.Train.TrainId));Assert.AreEqual(1350,state.GetHp("op_kyle"));Assert.AreEqual(900,state.GetHp("op_reina"));
  Assert.IsTrue((bool)reopened.ScheduleResolvedOrdinaryEffect(fatal)["replayed"]);reopened.Advance(5000000,10);Assert.AreEqual(terminal,reopened.CaptureCommittedState());
 }
 static JObject E()=>OrdinaryTrainInitialStateTests.Export();
 internal static OrdinaryFiveSeraFactory Factory(){var e=E();var start=OrdinaryFiveStartInput.Read((JObject)e["originalStart"],(string)e["accountId"],(string)e["runId"]);return OrdinaryFiveSeraFactory.FromInitialization(start,e["initializationResponse"].ToString(),500000);}
 internal static JObject Damage(string target,string kind,long sequence=1,long at=50){var e=E();var def=kind=="TRAIN"?new JObject{["numerator"]="111",["denominator"]="1"}:e["initializationResponse"]["initializationReceipt"]["stats"]["actors"].Single(a=>(string)a["operatorId"]==target)["effectiveStats"]["defense"].DeepClone();return new JObject{["sequence"]=sequence,["command"]=new JObject{["kind"]="ORDINARY_DAMAGE",["eventId"]="hit-"+sequence,["actionId"]="attack-"+sequence,["atMs"]=at,["accountId"]="a",["runId"]=e["runId"],["targetKind"]=kind,["healthTargetId"]=target,["protected"]=false,["numeric"]=new JObject{["version"]=CombatNumericDefenseBudget.Version,["base"]=new JObject{["numerator"]="253",["denominator"]="4"},["defense"]=def,["effects"]=new JArray(),["weakening"]=new JArray(),["penetration"]=new JArray(),["reductions"]=new JObject{["equipment"]=new JArray(),["guardStance"]=new JArray(),["independent"]=new JArray()}}}};}
 internal static JObject Schedule(BasicCombatSimulation model,JObject request){var method=typeof(BasicCombatSimulation).GetMethod("ScheduleResolvedOrdinaryEffect");Assert.NotNull(method,"Native six-target damage must reach the existing owner");try{return (JObject)method.Invoke(model,new object[]{request});}catch(TargetInvocationException e){throw e.InnerException;}}
 [Test] public void TrainAndOperatorDamageShareClockButNotHpAndRestoreWithoutReplay(){var f=Factory();var m=f.Create();var train=Damage(f.Original.Train.TrainId,"TRAIN");var op=Damage("op_kyle","OPERATOR",2);Schedule(m,train);Schedule(m,op);m.Advance(500000,1);Assert.AreEqual(4944,m.GetHp(f.Original.Train.TrainId));Assert.Less(m.GetHp("op_kyle"),1400);Assert.AreEqual(900,m.GetHp("op_reina"));var saved=m.CaptureLocalState();var restored=BasicCombatSimulation.RestoreLocalState(saved,f.Create);Assert.IsTrue((bool)Schedule(restored,train)["replayed"]);Assert.AreEqual(saved,restored.CaptureLocalState());Assert.AreEqual(2,restored.ReadSeraEmissions().Count);}
 [Test] public void WrongTargetKindAndScopeFailBeforeAnyMutation(){var f=Factory();var m=f.Create();var bad=Damage(f.Original.Train.TrainId,"TRAIN");bad["command"]["targetKind"]="OPERATOR";var before=m.CaptureLocalState();Assert.Throws<ArgumentException>(()=>Schedule(m,bad));Assert.AreEqual(before,m.CaptureLocalState());bad=Damage("op_kyle","OPERATOR");bad["command"]["accountId"]="other";Assert.Throws<ArgumentException>(()=>Schedule(m,bad));Assert.AreEqual(before,m.CaptureLocalState());}
 internal static JObject Shield(string target,string kind,long seq,long at=50,int amount=100){var r=Damage(target,kind,seq,at);var c=(JObject)r["command"];c.Remove("numeric");c.Remove("protected");c["kind"]="ORDINARY_SHIELD";c["sourceId"]=target;c["abilityId"]="SYNTHETIC_RESOLVED_SHIELD";c["effectIndex"]=0;c["amount"]=amount;c["expiryMs"]=500;return r;}
 [TestCase(true)][TestCase(false)] public void SameTickShieldUsesIssuedSequenceAndNeverProtectsAnotherTarget(bool shieldFirst){var f=Factory();var m=f.Create();string train=f.Original.Train.TrainId;Schedule(m,Shield(train,"TRAIN",shieldFirst?1:2));Schedule(m,Damage(train,"TRAIN",shieldFirst?2:1));Schedule(m,Damage("op_kyle","OPERATOR",3));m.Advance(500000,1);Assert.AreEqual(shieldFirst?5000:4944,m.GetHp(train));Assert.AreEqual(1350,m.GetHp("op_kyle"));var saved=m.CaptureLocalState();Assert.AreEqual(saved,BasicCombatSimulation.RestoreLocalState(saved,f.Create).CaptureLocalState());}
 [Test] public void TrainFailureCommitsAfterSameTickPrefixAndRejectsLaterEffects(){var f=Factory();var m=f.Create();var fatal=Damage(f.Original.Train.TrainId,"TRAIN");fatal["command"]["numeric"]["base"]=new JObject{["numerator"]="100000",["denominator"]="1"};Schedule(m,fatal);Schedule(m,Damage("op_kyle","OPERATOR",2));Schedule(m,Damage("op_reina","OPERATOR",3,100));m.Advance(5000000,10);Assert.AreEqual(BasicCombatOutcome.Failure,m.Outcome);Assert.AreEqual(1,m.Tick);Assert.AreEqual(1350,m.GetHp("op_kyle"));Assert.AreEqual(900,m.GetHp("op_reina"));var saved=m.CaptureLocalState();var restored=BasicCombatSimulation.RestoreLocalState(saved,f.Create);Assert.AreEqual(BasicCombatOutcome.Failure,restored.Outcome);Assert.AreEqual("REJECTED_TERMINAL",(string)Schedule(restored,Damage("op_kyle","OPERATOR",4,200))["status"]);restored.Advance(500000,1);Assert.AreEqual(saved,restored.CaptureLocalState());}
 [Test] public void OperatorDownDoesNotDestroyTrain(){var f=Factory();var m=f.Create();var fatal=Damage("op_kyle","OPERATOR");fatal["command"]["numeric"]["base"]=new JObject{["numerator"]="100000",["denominator"]="1"};Schedule(m,fatal);m.Advance(500000,1);Assert.AreEqual(0,m.GetHp("op_kyle"));Assert.AreEqual(5000,m.GetHp(f.Original.Train.TrainId));Assert.AreEqual(BasicCombatOutcome.Running,m.Outcome);}
 [Test] public void SceneCommitFailurePublishesNoDamageAndRecoveryAppliesPendingDamageOnce(){
  var f=Factory();var e=E();var start=e["originalStart"];string preview=(string)start["operationPreviewId"];
  var response=new JObject{["accepted"]=true,["lookupStatus"]="COMMITTED",["runId"]=f.Original.RunId,["runStatus"]="ACTIVE",["startResponse"]=start,["errorCode"]=null};
  var original=new PendingAccountAction("a","departure-start",preview,0,"damage-qa",new JObject{["operationPreviewId"]=preview}.ToString(),response.ToString(Newtonsoft.Json.Formatting.None));
  string stored=null;bool fail=false;var store=new CombatCheckpointStore("D:/Project/LASTRAIL/LocalTemp/Unity/damage-"+Guid.NewGuid()+".json",()=>stored,s=>{if(fail)throw new IOException("injected");stored=s;});
  var binding=new OrdinaryFiveSeraCheckpoint(store,original,f,new AppBuildSnapshot("damage-qa",1));binding.Save(f.Create(),0);var driver=CombatSceneDriver.ForOrdinarySeraStart(binding,()=>true);driver.Open();driver.ScheduleResolvedOrdinaryEffect(Damage(f.Original.Train.TrainId,"TRAIN"));driver.ScheduleResolvedOrdinaryEffect(Damage("op_kyle","OPERATOR",2));var before=driver.StateJson;fail=true;Assert.Throws<IOException>(()=>driver.Advance(500000,1));Assert.AreEqual(before,driver.StateJson);Assert.IsTrue(driver.RecoveryRequired);fail=false;driver.Open();driver.SetPaused(false);driver.Advance(500000,1);var saved=binding.Restore();Assert.AreEqual(4944,saved.Simulation.GetHp(f.Original.Train.TrainId));Assert.AreEqual(1350,saved.Simulation.GetHp("op_kyle"));Assert.AreEqual(2,saved.Simulation.ReadSeraEmissions().Count);
 }
 [Test] public void WriteResolvedEffectPlayerFixtureWithPendingSecondTrainImpact(){var f=Factory();var e=E();var effects=new JArray(Shield(f.Original.Train.TrainId,"TRAIN",3),Damage(f.Original.Train.TrainId,"TRAIN",4),Damage("op_kyle","OPERATOR",5),Damage(f.Original.Train.TrainId,"TRAIN",6,300));e["nativeResolvedEffects"]=effects;e["nativeEffectClassification"]="SYNTHETIC_TRUSTED_EFFECTS_NOT_ACTUAL_ENEMY_OR_RAIL_IMPACT";var m=f.Create();foreach(JObject r in effects)Schedule(m,r);m.Advance(2000000,20);Assert.AreEqual(5000,m.GetHp(f.Original.Train.TrainId));Assert.AreEqual(1350,m.GetHp("op_kyle"));var restored=BasicCombatSimulation.RestoreLocalState(m.CaptureLocalState(),f.Create);restored.Advance(2000000,20);Assert.AreEqual(4988,restored.GetHp(f.Original.Train.TrainId));string path="D:/Project/LASTRAIL/QA/OperatorInformation-20261019/OrdinaryDamage788";Directory.CreateDirectory(path);File.WriteAllText(path+"/player-input.json",e.ToString(Newtonsoft.Json.Formatting.None));}
}
